package bo.colbert.cobros;

import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import android.content.Context;
import android.graphics.*;
import org.junit.*;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.*;
import java.util.*;
import java.util.concurrent.*;
import bo.colbert.licensing.*;

@RunWith(AndroidJUnit4.class)
public class BillingTest {
 Context context;BillingDb db;String name,token;long now=java.time.Instant.parse("2026-10-31T16:00:00Z").toEpochMilli();
 @Before public void setup()throws Exception{context=InstrumentationRegistry.getInstrumentation().getTargetContext();name="billing-test-"+UUID.randomUUID()+".db";db=new BillingDb(context,name);token=LicenseProtocol.random();db.create("tenant-one","Cliente de prueba","comedor","Comedor",token,now);}
 @After public void close(){db.close();context.deleteDatabase(name);}
 JSONObject status()throws Exception{return db.status("tenant-one",LicenseProtocol.random(),now);}
 void charge(String interval)throws Exception{db.plan("tenant-one",1000,interval,"Pagar a la cuenta de prueba", "",now);db.charge("tenant-one",now);}
 static String picture(int color)throws Exception{Bitmap b=Bitmap.createBitmap(40,40,Bitmap.Config.ARGB_8888);b.eraseColor(color);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return Base64.getEncoder().encodeToString(out.toByteArray());}
 JSONObject request(String invoice,String image)throws Exception{return new JSONObject().put("requestId",UUID.randomUUID().toString()).put("invoiceId",invoice).put("image",image).put("note","Referencia 123");}
 JSONObject upload()throws Exception{return db.receipt("tenant-one",request(status().getJSONObject("invoice").getString("id"),picture(Color.BLUE)),now);}
 interface Throwing{void run()throws Exception;}
 void reject(Throwing r)throws Exception{try{r.run();fail("Se debió rechazar");}catch(IllegalArgumentException|SecurityException expected){}}
 @Test public void startsFreeAndAppliesExactlyTwentyFourHourLease()throws Exception{JSONObject s=status();assertTrue(s.getBoolean("allowed"));assertEquals(0,s.getLong("paidUntil"));assertEquals(LicenseProtocol.OFFLINE_MS,s.getLong("expiresAt")-now);assertFalse(s.has("invoice"));}
 @Test public void onlyCorrectContractTokenAuthenticates()throws Exception{assertEquals("tenant-one",db.authenticate(token).getString("id"));reject(()->db.authenticate(LicenseProtocol.random()));reject(()->db.authenticate(""));}
 @Test public void chargeAndUploadDoNotGrantAccess()throws Exception{charge("month");assertFalse(status().getBoolean("allowed"));JSONObject receipt=upload();assertEquals("pending",receipt.getString("state"));assertFalse(status().getBoolean("allowed"));assertEquals(1,db.pending().length());}
 @Test public void priceChangesPreserveIssuedInvoiceAndRequireExplicitReplacement()throws Exception{charge("day");JSONObject original=status().getJSONObject("invoice");db.plan("tenant-one",2000,"month","Nueva cuenta","",now);assertEquals(1000,status().getJSONObject("invoice").getLong("amountMinor"));db.charge("tenant-one",now);assertEquals(original.getString("id"),status().getJSONObject("invoice").getString("id"));db.revise("tenant-one",now);assertEquals(2000,status().getJSONObject("invoice").getLong("amountMinor"));assertEquals("cancelled",db.get("invoice",original.getString("id")).getString("state"));}
 @Test public void pendingProofCannotBeSilentlyCancelledByPriceReplacement()throws Exception{charge("day");upload();reject(()->db.revise("tenant-one",now));}
 @Test public void approvalIsAtomicAndIdempotentForAllDevices()throws Exception{charge("month");String id=upload().getString("receiptId");ExecutorService workers=Executors.newFixedThreadPool(2);try{Future<?> a=workers.submit(()->{try{db.review(id,true,"Verificado",now);}catch(Exception e){throw new RuntimeException(e);}});Future<?> b=workers.submit(()->{try{db.review(id,true,"Verificado",now);}catch(Exception e){throw new RuntimeException(e);}});a.get();b.get();}finally{workers.shutdownNow();}assertEquals(BillingDb.extend(now,"month"),status().getLong("paidUntil"));assertTrue(status().getBoolean("allowed"));assertTrue(db.status("tenant-one",LicenseProtocol.random(),now).getBoolean("allowed"));assertEquals(0,db.pending().length());}
 @Test public void monthlyPeriodClampsCalendarEndAndDailyPeriodExpiresExactly()throws Exception{assertEquals(java.time.Instant.parse("2026-11-30T16:00:00Z").toEpochMilli(),BillingDb.extend(now,"month"));charge("day");db.review(upload().getString("receiptId"),true,"",now);long end=BillingDb.extend(now,"day");assertTrue(db.status("tenant-one",LicenseProtocol.random(),end-1).getBoolean("allowed"));JSONObject expired=db.status("tenant-one",LicenseProtocol.random(),end);assertFalse(expired.getBoolean("allowed"));assertTrue(expired.has("invoice"));}
 @Test public void leaseNeverOutlivesPaidPeriod()throws Exception{charge("day");db.review(upload().getString("receiptId"),true,"",now);JSONObject near=db.status("tenant-one",LicenseProtocol.random(),now+23*3600000L);assertEquals(now+86400000L,near.getLong("expiresAt"));}
 @Test public void receiptRetryReturnsSameRequestAndRejectsChangedPayload()throws Exception{charge("month");JSONObject req=request(status().getJSONObject("invoice").getString("id"),picture(Color.BLUE));JSONObject first=db.receipt("tenant-one",req,now);assertEquals(first.getString("receiptId"),db.receipt("tenant-one",req,now+1).getString("receiptId"));assertEquals(1,db.pending().length());req.put("note","otra referencia");reject(()->db.receipt("tenant-one",req,now));}
 @Test public void receiptForOtherCustomerAndInvalidImagesAreRejected()throws Exception{charge("day");String other=LicenseProtocol.random();db.create("tenant-two","Otro cliente","comedor","Comedor",other,now);JSONObject req=request(status().getJSONObject("invoice").getString("id"),picture(Color.GREEN));reject(()->db.receipt("tenant-two",req,now));req.put("image",Base64.getEncoder().encodeToString("not an image".getBytes(StandardCharsets.UTF_8)));reject(()->db.receipt("tenant-one",req,now));}
 @Test public void rejectionKeepsLockedAndSameApprovedPictureCannotPayAgain()throws Exception{charge("day");String invoice=status().getJSONObject("invoice").getString("id");JSONObject first=db.receipt("tenant-one",request(invoice,picture(Color.BLUE)),now);db.review(first.getString("receiptId"),false,"No aparece el abono",now);assertFalse(status().getBoolean("allowed"));JSONObject second=db.receipt("tenant-one",request(invoice,picture(Color.GREEN)),now);db.review(second.getString("receiptId"),true,"",now);now+=86400000L;String next=status().getJSONObject("invoice").getString("id");reject(()->db.receipt("tenant-one",request(next,picture(Color.GREEN)),now));}
 @Test public void productContractsStayIsolatedAndManualFreeUnlocks()throws Exception{charge("month");db.create("desktop","Cliente de prueba","desktop-tool","Programa PC",LicenseProtocol.random(),now);assertTrue(db.status("desktop",LicenseProtocol.random(),now).getBoolean("allowed"));db.suspend("tenant-one",now);assertEquals("suspended",status().getString("reason"));db.free("tenant-one",now);assertTrue(status().getBoolean("allowed"));}
 @Test public void encryptedBackupPreservesProofsAndRejectsWrongPassword()throws Exception{charge("day");String receipt=upload().getString("receiptId");JSONObject data=db.exportData();byte[] encrypted=BillingBackup.encrypt(data,"password-long-123".toCharArray());assertFalse(new String(encrypted,StandardCharsets.UTF_8).contains("Cliente de prueba"));JSONObject recovered=BillingBackup.decrypt(encrypted,"password-long-123".toCharArray());String otherName=name+"-restore";try(BillingDb restored=new BillingDb(context,otherName)){restored.restore(recovered);assertEquals(db.get("receipt",receipt).getString("image"),restored.get("receipt",receipt).getString("image"));assertEquals(db.contracts().toString(),restored.contracts().toString());}finally{context.deleteDatabase(otherName);}try{BillingBackup.decrypt(encrypted,"wrong-password".toCharArray());fail("Wrong password accepted");}catch(javax.crypto.AEADBadTagException expected){}}
 @Test public void publicHttpRejectsAdministrationAndSignsCustomerStatus()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));KeyPair keys=g.generateKeyPair();try(BillingHttp http=new BillingHttp(db,c->LicenseProtocol.sign(c,keys.getPrivate(),keys.getPublic()))){http.start(0);assertEquals(404,http(http.port(),"POST","/admin/approve",token,new JSONObject()).getInt("code"));assertEquals(403,http(http.port(),"POST","/v1/status",LicenseProtocol.random(),new JSONObject()).getInt("code"));String nonce=LicenseProtocol.random();JSONObject result=http(http.port(),"POST","/v1/status",token,new JSONObject().put("nonce",nonce));assertEquals(200,result.getInt("code"));JSONObject envelope=result.getJSONObject("body");JSONObject claims=LicenseProtocol.verify(envelope,Base64.getEncoder().encodeToString(keys.getPublic().getEncoded()),"tenant-one","comedor",nonce);assertTrue(claims.getBoolean("allowed"));}}
 static JSONObject http(int port,String method,String path,String token,JSONObject data)throws Exception{try(Socket socket=new Socket("127.0.0.1",port)){socket.setSoTimeout(5000);byte[] body=data.toString().getBytes(StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();out.write((method+" "+path+" HTTP/1.1\r\nHost: localhost\r\nAuthorization: Bearer "+token+"\r\nContent-Length: "+body.length+"\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(body);out.flush();String reply=new String(LicenseClient.read(socket.getInputStream(),4*1024*1024),StandardCharsets.UTF_8);return new JSONObject().put("code",Integer.parseInt(reply.split(" ")[1])).put("body",new JSONObject(reply.substring(reply.indexOf("\r\n\r\n")+4)));}}
}
